const url = $json.url.split('#')[0];
const parts = url.match(/^(https?:\/\/)([^\/?#]+)(\/[^?#]*)?(\?[^#]*)?$/i);
if (!parts || !$json.site) throw new Error('Invalid portal crawl');
const origin = parts[1].toLowerCase() + parts[2].toLowerCase().replace(/:(80|443)$/, '');
const section = $("Webhook (Crawl Trigger)").first().json.body.scope === 'section';
return [{ json: {
  targetUrl: url,
  origin,
  targetHostname: parts[2].toLowerCase().replace(/:(80|443)$/, ''),
  scopePath: (parts[3] || '/').replace(/\/+$/, '') || '/',
  section,
  limit: section ? 25 : 1,
  siteName: $json.site,
  excludePaths: [],
  recheckIntervalHours: 168,
  robotsUrl: origin + '/robots.txt',
  sitemapUrl: origin + '/sitemap.xml'
} }];

const response = $input.first().json;
const status = Number(response.statusCode);
const missing = status === 404 || status === 410;
const body = response.data ?? response.body;
const contentType = response.headers?.['content-type'] || '';
const available = missing || (status >= 200 && status < 300 && typeof body === 'string' && !/^text\/html\b/i.test(contentType));
const raw = available && !missing ? body : '';
const config = $("⚙️ Workflow Config (修改网站入口)").first().json;
const sitemapUrls = [];
const lines = raw.split('\n');

const groups = [];
let currentGroup = null;

for (let line of lines) {
  line = line.replace(/#.*$/, '').trim();
  if (!line) continue;

  const colonIdx = line.indexOf(':');
  if (colonIdx === -1) continue;

  const directive = line.substring(0, colonIdx).trim().toLowerCase();
  const value = line.substring(colonIdx + 1).trim();

  if (directive === 'sitemap' &&
      (value.startsWith(config.origin + '/') || value.startsWith(config.origin.replace(/^http:/, 'https:') + '/'))) {
    sitemapUrls.push(value);
  }
  if (directive === 'user-agent') {
    const agent = value.toLowerCase();
    if (!currentGroup || currentGroup.hasRules) {
      currentGroup = { agents: [], rules: [], hasRules: false };
      groups.push(currentGroup);
    }
    currentGroup.agents.push(agent);
  } else if (currentGroup && (directive === 'disallow' || directive === 'allow')) {
    currentGroup.hasRules = true;
    if (!value) continue;

    const hasEndAnchor = value.endsWith('$');
    const cleanVal = hasEndAnchor ? value.slice(0, -1) : value;

    let regexStr = cleanVal
      .replace(/[.+?^${}()|[\]\\]/g, '\\$&')
      .replace(/\*/g, '.*');

    regexStr = '^' + regexStr + (hasEndAnchor ? '$' : '.*');

    currentGroup.rules.push({
      type: directive,
      path: value,
      pattern: regexStr,
      length: value.length
    });
  }
}

// 匹配优先级：优先专属 agent (crawl4ai)，若无则降级匹配通配符 *

const specific = groups.filter(group => group.agents.includes('crawl4ai'));
const rules = (specific.length ? specific : groups.filter(group => group.agents.includes('*')))
  .flatMap(group => group.rules);
const seedPath = config.targetUrl.match(/^https?:\/\/[^/?#]+(.*)$/i)?.[1] || '/';
const seedRules = rules.filter(rule => new RegExp(rule.pattern).test(seedPath.startsWith('?') ? '/' + seedPath : seedPath))
  .sort((a, b) => b.length - a.length || Number(b.type === 'allow') - Number(a.type === 'allow'));
return [{ json: {
  available, rules,
  seedAllowed: seedRules[0]?.type !== 'disallow',
  sitemapUrl: sitemapUrls[0] || config.sitemapUrl
} }];

const config = $("⚙️ Workflow Config (修改网站入口)").first().json;
const entries = $input.first().json.sitemapindex?.sitemap || [];
const urls = [...new Set([entries].flat().map(entry => entry?.loc)
  .filter(url => typeof url === 'string' &&
    (url.startsWith(config.origin + '/') || url.startsWith(config.origin.replace(/^http:/, 'https:') + '/'))))];
const hint = config.scopePath.split('/')[1]?.toLowerCase();
if (hint) urls.sort((a, b) => Number(b.toLowerCase().includes(hint)) - Number(a.toLowerCase().includes(hint)));
return urls.length ? urls.slice(0, 3).map(sitemapUrl => ({ json: { sitemapUrl } })) : [{ json: {} }];

function scopedUrl(value, config) {
  let href = (value || '').trim().split('#')[0];
  if (!href || /[\s\\]/.test(href)) return null;
  if (href.startsWith('//')) href = config.origin.split(':')[0] + ':' + href;
  if (!/^[a-z][a-z0-9+.-]*:/i.test(href)) {
    const seedPath = config.targetUrl.match(/^https?:\/\/[^/?#]+(\/[^?#]*)?/i)?.[1] || '/';
    const path = href.startsWith('/') ? href
      : href.startsWith('?') ? seedPath + href
      : seedPath.slice(0, seedPath.lastIndexOf('/') + 1) + href;
    href = config.origin + path;
  }
  const parts = href.match(/^(https?:\/\/[^/?#]+)(\/[^?#]*)?(\?[^#]*)?$/i);
  if (!parts) return null;
  const origin = parts[1].toLowerCase().replace(/:(80|443)$/, '');
  if (origin !== config.origin && origin !== config.origin.replace(/^http:/, 'https:')) return null;

  const inputPath = parts[2] || '/';
  const segments = [];
  for (const segment of inputPath.split('/')) {
    const dot = segment.replace(/%2e/gi, '.');
    if (!dot || dot === '.') continue;
    if (dot === '..') { segments.pop(); continue; }
    if (/%2f|%5c/i.test(segment)) return null;
    segments.push(segment);
  }
  const pathname = '/' + segments.join('/');
  if (config.section
        ? config.scopePath !== '/' && pathname !== config.scopePath && !pathname.startsWith(config.scopePath + '/')
        : pathname !== config.scopePath || (parts[3] || '') !== (config.targetUrl.match(/\?.*$/)?.[0] || ''))
    return null;
  return origin + pathname + (pathname !== '/' && inputPath.endsWith('/') ? '/' : '') + (parts[3] || '');
}

const config = $("⚙️ Workflow Config (修改网站入口)").first().json;
const candidates = new Map();
const key = url => url.replace(/\/(?=\?|$)/, '');
const seed = config.targetUrl;
candidates.set(key(seed), { url: seed, sourceOrigin: 'seed', lastmod: null });
let sitemapCount = 0;
let probeCount = 0;
function add(url, sourceOrigin, lastmod = null) {
  const scoped = scopedUrl(url, config);
  if (!scoped) return false;
  const id = key(scoped);
  if (!candidates.has(id)) candidates.set(id, { url: scoped, sourceOrigin, lastmod });
  else if (lastmod && !candidates.get(id).lastmod) candidates.get(id).lastmod = lastmod;
  return true;
}

if (config.section) {
  const html = $("Fetch Homepage (First-Level Discovery)").isExecuted ? $("Fetch Homepage (First-Level Discovery)").first()?.json?.data : '';
  if (typeof html === 'string') {
    const links = /href\s*=\s*["']([^"'#\s>]+)["']/gi;
    for (const [, href] of html.matchAll(links))
      if (add(href.replace(/&amp;/gi, '&'), 'homepage_probe')) probeCount++;
  }

  const sitemaps = [$("XML to JSON (Index)"), $("XML to JSON (Child)")];
  for (const node of sitemaps) {
    if (!node.isExecuted) continue;
    for (const item of node.all()) {
      const entries = item.json.urlset?.url || [];
      for (const entry of [entries].flat())
        if (add(entry?.loc, 'sitemap', typeof entry?.lastmod === 'string' ? entry.lastmod.trim() : null)) sitemapCount++;
    }
  }
}

const discovery = { sitemapCount, probeCount, rawDiscoveredCount: 1 + sitemapCount + probeCount,
  uniquePagesCount: candidates.size };
return Array.from(candidates.values()).map(item => ({ json: { ...item, discovery } }));

const config = $('⚙️ Workflow Config (修改网站入口)').first().json;
const targetHostname = config.targetHostname;
const robotsNodeData = $('Parse robots.txt Rules').first()?.json || {};
const robotsRules = robotsNodeData.rules || robotsNodeData.disallowRegexes || [];
const userExcludePaths = config.excludePaths || [];
const recheckIntervalHours = config.recheckIntervalHours || 168; // 默认7天

let crawlIndex = {};
try {
  const rawIndex = $('Fetch Crawl Index').first()?.json;
  if (rawIndex && typeof rawIndex === 'object' && !rawIndex.error && !rawIndex.statusCode) {
    for (const [k, v] of Object.entries(rawIndex)) {
      crawlIndex[k.replace(/\/+$/, '')] = v;
    }
  }
} catch (e) {
  crawlIndex = {};
}

const incomingItems = $input.all();
const validUrls = [];
const seenUrlsInBatch = new Set();
const redirectsFiltered = [];
const blockedByRobots = [];
const blockedStatic = [];
const unchangedSkipped = [];


for (const item of incomingItems) {
  const rawUrl = (item.json.url || '').trim();
  const key = rawUrl.replace(/\/+$/, '');
  const lastmod = item.json.lastmod || null;
  if (!rawUrl) continue;

  try {
    const match = rawUrl.match(/^https?:\/\/([^\/\?]+)(\/[^\?]*)?(\?.*)?$/i);
    if (!match) continue;

    const hostname = (match[1] || '').toLowerCase().replace(/:(80|443)$/, '');
    const pathname = match[2] || '/';
    const search = match[3] || '';

    // 1. 严格域名限制 (Strict Domain Boundary)
    if (!robotsNodeData.available || hostname !== targetHostname) continue;

    // 2. 静态与系统资源过滤
    if (/\.(png|jpg|jpeg|gif|svg|webp|pdf|zip|mp4|css|js|woff|woff2|ico|xml|rss|atom|json|txt)$/i.test(pathname)) continue;
    if (/blog-feed|sitemap|robots\.txt/i.test(pathname)) continue;

    // 3. 用户自定义路径黑名单 (Config 动态输入，零硬编码)
    let isUserExcluded = false;
    for (const pattern of userExcludePaths) {
      if (!pattern) continue;
      if (pathname.includes(pattern) || new RegExp(pattern, 'i').test(pathname)) {
        redirectsFiltered.push({
          url: rawUrl,
          reason: `Matched user exclude pattern: "${pattern}"`
        });
        isUserExcluded = true;
        break;
      }
    }
    if (isUserExcluded) continue;

    // 4. 网关即时去重
    if (seenUrlsInBatch.has(key)) continue;
    seenUrlsInBatch.add(key);

    // 5. robots.txt RFC 9309 规范判定 (特异度最长规则优先，等长 Allow 优先)
    const pathAndQuery = pathname + search;
    let bestMatch = null;

    for (const rule of robotsRules) {
      const pattern = typeof rule === 'string' ? rule : rule.pattern;
      const type = typeof rule === 'string' ? 'disallow' : rule.type;
      const len = typeof rule === 'string' ? pattern.length : (rule.length || 0);

      try {
        if (new RegExp(pattern).test(pathAndQuery)) {
          if (!bestMatch || len > bestMatch.len) {
            bestMatch = { type, len, pattern };
          } else if (len === bestMatch.len && type === 'allow') {
            bestMatch = { type, len, pattern };
          }
        }
      } catch (e) {}
    }

    if (bestMatch && bestMatch.type === 'disallow') {
      blockedByRobots.push({ url: rawUrl, reason: `Disallowed by robots.txt rule: "${bestMatch.pattern}"` });
      continue;
    }

    // 6. 【三级增量决策体系 (Three-Tier Incremental Engine)】
    const indexedInfo = crawlIndex[key];
    let shouldCrawl = true;
    let skipReason = '';

    if (indexedInfo && indexedInfo.fileName && indexedInfo.hash) {
      if (lastmod && indexedInfo.lastmod) {
        if (lastmod <= indexedInfo.lastmod) {
          shouldCrawl = false;
          skipReason = `Sitemap lastmod unchanged (${lastmod} <= ${indexedInfo.lastmod})`;
        }
      } else {
        const lastCrawlMs = indexedInfo.lastCrawlTime ? new Date(indexedInfo.lastCrawlTime).getTime() : 0;
        const hoursPassed = (Date.now() - lastCrawlMs) / (1000 * 60 * 60);
        if (hoursPassed < recheckIntervalHours) {
          shouldCrawl = false;
          skipReason = `No lastmod provided; crawled ${Math.round(hoursPassed)}h ago (within ${recheckIntervalHours}h verification TTL)`;
        } else {
          shouldCrawl = true;
        }
      }
    }

    if (!shouldCrawl) {
      unchangedSkipped.push({
        url: rawUrl,
        lastmod: lastmod,
        indexedLastmod: indexedInfo?.lastmod,
        reason: skipReason
      });
      continue;
    }

    validUrls.push({
      url: rawUrl,
      lastmod: lastmod,
      hostname: hostname,
      pathname: pathname,
      isRecheck: !!(indexedInfo && indexedInfo.hash)
    });
  } catch (err) {}
}

// 7. 【线上删除页面探查 (Stale Webpage Detection)】

const queued = validUrls.slice(0, config.limit);
return [{ json: {
  urlsToCrawlCount: queued.length,
  validUrls: queued,
  diagnostics: { ...incomingItems[0]?.json.discovery, redirectsFiltered, unchangedSkipped, blockedByRobots, blockedStatic },
  failureCode: robotsNodeData.available ? null : 'robots-unavailable'
} }];

